alter table public.customer_profiles add column password_hash text;
alter table public.customer_profiles add column password_salt text;

create table public.customer_sessions (
  id uuid primary key default gen_random_uuid(),
  customer_profile_id uuid not null references public.customer_profiles(id) on delete cascade,
  token_hash text not null unique,
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);

create index customer_sessions_token_hash_idx on public.customer_sessions (token_hash);
create index customer_sessions_expires_at_idx on public.customer_sessions (expires_at);

alter table public.customer_sessions enable row level security;
revoke all on public.customer_sessions from anon, authenticated;
